import unittest
from unittest.mock import patch, MagicMock
import time

class TestVirtualSystem(unittest.TestCase):

    def setUp(self):
        self.patient_service = MagicMock()
        self.admin_service = MagicMock()
        self.system_monitor = MagicMock()

    @patch('time.time')
    def test_patient_registration_within_limits(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        patient_info = {
            "name": "John Doe",
            "age": 30,
            "medical_info": "Hypertension",
            "general_info": "No allergies"
        }
        self.patient_service.register_patient.return_value = True
        result = self.patient_service.register_patient(patient_info)
        self.assertTrue(result)

    @patch('time.time')
    def test_patient_registration_invalid_age(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        patient_info = {
            "name": "John Doe",
            "age": -5,
            "medical_info": "Hypertension",
            "general_info": "No allergies"
        }
        with self.assertRaises(ValueError) as context:
            self.patient_service.register_patient(patient_info)
        self.assertEqual(str(context.exception), "Invalid age")

    @patch('time.time')
    def test_add_specialty_within_limits(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        specialty_name = "Cardiology"
        self.admin_service.add_specialty.return_value = True
        result = self.admin_service.add_specialty(specialty_name)
        self.assertTrue(result)

    @patch('time.time')
    def test_add_specialty_empty_name(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        specialty_name = ""
        with self.assertRaises(ValueError) as context:
            self.admin_service.add_specialty(specialty_name)
        self.assertEqual(str(context.exception), "Specialty name cannot be empty")

    @patch('time.time')
    def test_register_doctor_within_limits(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        doctor_info = {
            "name": "Dr. Smith",
            "specialty": "Cardiology"
        }
        self.admin_service.register_doctor.return_value = True
        result = self.admin_service.register_doctor(doctor_info)
        self.assertTrue(result)

    @patch('time.time')
    def test_register_doctor_specialty_not_found(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp
        doctor_info = {
            "name": "Dr. Smith",
            "specialty": "Nonexistent Specialty"
        }
        with self.assertRaises(ValueError) as context:
            self.admin_service.register_doctor(doctor_info)
        self.assertEqual(str(context.exception), "Specialty not found")

    @patch('time.time')
    def test_response_time_critical_functionality(self, mock_time):
        mock_time.side_effect = [1696076400, 1696076401.5]  # Start and end times
        self.system_monitor.measure_response_time.return_value = 1.5
        response_time = self.system_monitor.measure_response_time()
        self.assertLessEqual(response_time, 2)

    @patch('time.time')
    def test_response_time_other_functions_peak(self, mock_time):
        mock_time.side_effect = [1696076400, 1696076403.5]  # Start and end times
        self.system_monitor.measure_response_time.return_value = 3.5
        response_time = self.system_monitor.measure_response_time()
        self.assertLessEqual(response_time, 4)

    @patch('time.time')
    def test_system_availability_during_outage(self, mock_time):
        mock_time.return_value = 1696076400  # Example timestamp during outage window
        self.system_monitor.is_system_available.return_value = False
        availability = self.system_monitor.is_system_available()
        self.assertFalse(availability)

    @patch('time.time')
    def test_system_availability_outside_outage(self, mock_time):
        mock_time.return_value = 1696076460  # Example timestamp outside outage window
        self.system_monitor.is_system_available.return_value = True
        availability = self.system_monitor.is_system_available()
        self.assertTrue(availability)

    @patch('time.time')
    def test_system_availability_overall(self, mock_time):
        mock_time.side_effect = [1696076400, 1696076460, 1696076520, 1696076580]  # Example timestamps
        self.system_monitor.calculate_availability.return_value = 0.99999
        availability = self.system_monitor.calculate_availability()
        self.assertGreaterEqual(availability, 0.99999)

    @patch('concurrent.futures.ThreadPoolExecutor')
    def test_system_scaling_concurrent_users(self, mock_executor):
        mock_executor.return_value.__enter__.return_value.map.return_value = [True] * 10000
        results = self.system_monitor.test_concurrent_users(10000)
        self.assertTrue(all(results))

